// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.warp(1000);

        c.seedMarket(1000);

        address alice = address(0x123);
        vm.deal(alice, 1 ether);

        vm.prank(alice);
        c.getFreeKilo();

        vm.warp(1100);

        address bob = address(0x456);

        vm.prank(alice);
        c.collectDrugs(bob);


        uint256 bobClaimed = c.claimedDrugs(bob);

        assertTrue(bobClaimed == 6000, "Bob's claimedDrugs should be 6000 in correct contract");
    }
}
